        [TestMethod]
        [DynamicData(nameof(ToDateOnlyTestData), DynamicDataSourceType.Method)]
        public void ToDateOnly_WhenCalled_ShouldReturnExpectedDateOnly(DateTime input, DateTime expectedDateTime)
