            var expected = DateOnly.FromDateTime(expectedDateTime);

            var actual = input.ToDateOnly();

            Assert.AreEqual(expected, actual);
        }

        /// <summary>
        /// Verifies that To Date Only, when Kind Is Set, Ignore Kind.
        /// </summary>
        [TestMethod]
        [DataRow(DateTimeKind.Unspecified)]
